<script setup lang="ts">
import { logKinds, logPhases, logOutcomes, type LogDetail } from '../../app/logDetail'
import Timestamp from '../Timestamp.vue'
import CopyId from '../CopyId.vue'
import JsonText from '../JsonText.vue'
defineProps<{ data: LogDetail; raw: string }>()
const identities = [['request_id', '请求关联号'], ['task_id', '任务关联号'], ['step_id', '步骤关联号'], ['call_id', '逻辑调用关联号'], ['attempt_id', '尝试关联号']] as const
</script>
<template><div class="log-detail-content"><dl class="facts"><div><dt>日志源 / 世代</dt><dd>{{ data.source }} / {{ data.epoch }}</dd></div><div><dt>事件类型 / 阶段</dt><dd>{{ logKinds[data.kind] || data.kind }} / {{ logPhases[data.phase] || data.phase }}</dd></div><div><dt>发生时间</dt><dd><Timestamp :value="data.occurred_at" empty="未提供" /></dd></div><div><dt>入库时间</dt><dd><Timestamp :value="data.received_at" empty="未提供" /></dd></div><div><dt>执行结果</dt><dd>{{ data.outcome ? logOutcomes[data.outcome] || data.outcome : '当前事件未记录结果' }}</dd></div><div><dt>HTTP 状态</dt><dd>{{ data.http_status ?? '未记录' }}</dd></div><div><dt>业务结果码</dt><dd>{{ data.business_code === null ? '未记录' : Number.isSafeInteger(data.business_code) ? data.business_code : '超出精确数值范围，请查看原文' }}</dd></div><div><dt>耗时（纳秒）</dt><dd>{{ data.duration_ns ?? '未记录' }}</dd></div><div><dt>业务接口标识</dt><dd>{{ data.operation ?? '未提供' }}</dd></div><div><dt>尝试编号</dt><dd>{{ data.attempt_no ?? '未提供' }}</dd></div></dl><p v-if="data.phase !== 'finished'" class="hint">当前事件没有结束边界，不能据此推断调用已成功或仍在运行；结束记录可能另行入库。</p><p>事件号：<CopyId :value="data.event_id" label="日志事件号" /></p><p>实体关联号：<CopyId :value="data.entity_id" label="日志实体关联号" /></p><p v-for="[field, label] in identities" :key="field"><template v-if="data[field]">{{ label }}：<CopyId :value="data[field]" :label="label" /></template><template v-else>{{ label }}：未提供关联</template></p><p v-if="data.test">用途：{{ data.test.purpose === 'test' ? '显式测试' : '同步' }} <CopyId v-if="data.test.test_run_id" :value="data.test.test_run_id" label="测试关联号" /></p><p v-if="data.audit">审计动作：{{ data.audit.action }} · 操作者关联号 {{ data.audit.actor_id }} · 对象关联号 {{ data.audit.object_id }}</p><p class="hint">缺少关联可能尚未入库，也可能本事件没有该关系；不按相近时间合并调用。日志受保留策略约束，此详情未提供保留截止时间。</p><p class="hint">正文处理：{{ data.redaction.redacted ? '已记录脱敏处理' : '无附加正文脱敏标记' }} · 原始字节数 {{ data.redaction.original_bytes }} · 字段数 {{ data.redaction.field_count }}</p><p v-if="data.redaction.truncated || data.response?.truncated" class="warning">服务端已截断内容，不能视为完整响应。</p><p v-if="data.response?.read_error" class="warning">响应正文未完整读取，当前仅为已收到的证据。</p><JsonText :text="raw" :source-truncated="data.redaction.truncated || data.response?.truncated" label="日志脱敏详情" /></div></template>
<style scoped>.log-detail-content { min-width: 0; overflow-wrap: anywhere; } .log-detail-content > p { margin-block: 12px; }</style>